6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}: rejects a body that is missing or blank in any
13	 * required field (firstName, lastName, address, city, telephone) before {@link BuildOwner}
14	 * runs, so such a request is a 400 listing the offending fields rather than a persisted owner.
15	 *
16	 * <p>Reads the raw body (no {@code @Valid}) so this check runs ahead of bean validation and
17	 * owns the response format; the body is republished for later steps.
18	 *
19	 * <p>The address is normalized in place first (see {@link AddressNormalizer}) so the required
20	 * check rejects an address that is blank <em>after</em> normalization, and every later step
21	 * sees — and the response returns — the normalized address.
22	 */
23	public class RequireOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws MissingOwnerFieldsException {
27	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
28	        List<String> missing = new ArrayList<>();
29	        if (isBlank(request.getFirstName())) {
30	            missing.add("firstName");
31	        }
32	        if (isBlank(request.getLastName())) {
33	            missing.add("lastName");
34	        }
35	        if (isBlank(request.getAddress())) {
36	            missing.add("address");
37	        }
38	        if (isBlank(request.getCity())) {
39	            missing.add("city");
40	        }
41	        if (isBlank(request.getTelephone())) {
42	            missing.add("telephone");
43	        }
44	        if (!missing.isEmpty()) {
45	            throw new MissingOwnerFieldsException(missing);
46	        }
47	        validated.set(request);
48	    }
49	
50	    private static boolean isBlank(String value) {
51	        return value == null || value.isBlank();
52	    }
53	}
