3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create-owner request that shares a household with an existing owner: same
11	 * last name (compared case-insensitively with runs of whitespace collapsed to a single
12	 * space) and same address (compared in the normalized form of {@link AddressNormalizer}).
13	 * Runs before {@link BuildOwner}. A collision is rejected 409 via
14	 * {@link DuplicateHouseholdException}, unless the request opts in with
15	 * {@code sharesHousehold} set true.
16	 */
17	public class RejectDuplicateHousehold {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateHouseholdException {
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String lastName = normalize(request.getLastName());
25	        String address = AddressNormalizer.normalize(request.getAddress());
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (normalize(existing.getLastName()).equals(lastName)
28	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
29	                throw new DuplicateHouseholdException(
30	                        "Another owner with the same last name and address already exists");
31	            }
32	        }
33	    }
34	
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
40	    }
41	}
