22	        long count = ownerRepository.findAll().stream()
23	                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
24	                .count();
25	        if (count >= CITY_CAPACITY) {
26	            throw new CityAtCapacityException(
27	                    "City already contains the maximum number of owners");
28	        }
