1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share this
9	 * owner's {@code firstName} and {@code lastName}, compared case-insensitively.
10	 *
11	 * <p>Runs after {@link BuildOwner} (so the Owner exists) but before {@link SaveOwner} (so the
12	 * owner being created is not itself counted), mutating the owner in place so the persisted
13	 * value — and every later read — carries the count as it stood before this create.
14	 */
15	public class AssignNamesakeCount {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = normalize(owner.getFirstName());
19	        String lastName = normalize(owner.getLastName());
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (normalize(existing.getFirstName()).equals(firstName)
23	                    && normalize(existing.getLastName()).equals(lastName)) {
24	                count++;
25	            }
26	        }
27	        owner.setNamesakeCount(count);
28	    }
29	
30	    private static String normalize(String value) {
31	        return value == null ? "" : value.trim().toLowerCase();
32	    }
33	}
