1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Converts a raw telephone into E.164 form: a leading '+' and country code are kept when
7	 * present, otherwise country code '+61' is assumed and a single leading '0' is dropped from
8	 * the national digits. Spaces, dashes and brackets (indeed every non-digit character) are
9	 * stripped, and the result must carry 8 to 15 digits after the '+'.
10	 *
11	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
12	 * tripping the one-public-method-per-function rule.
13	 */
14	public final class E164Telephone {
15	
16	    private E164Telephone() {
17	    }
18	
19	    /**
20	     * @return the E.164 form ('+' followed by 8 to 15 digits).
21	     * @throws InvalidTelephoneException if the input cannot form valid E.164.
22	     */
23	    public static String normalize(String raw) throws InvalidTelephoneException {
24	        if (raw == null) {
25	            throw new InvalidTelephoneException("Telephone is required");
26	        }
27	        boolean hasCountryCode = raw.trim().startsWith("+");
28	        String digits = raw.replaceAll("\\D", "");
29	        if (!hasCountryCode) {
30	            if (digits.startsWith("0")) {
31	                digits = digits.substring(1);
32	            }
33	            digits = "61" + digits;
34	        }
35	        if (digits.length() < 8 || digits.length() > 15) {
36	            throw new InvalidTelephoneException(
37	                    "Telephone must have 8 to 15 digits in E.164 form");
38	        }
39	        return "+" + digits;
40	    }
41	
42	    /** E.164 form of a telephone, or {@code null} when it is absent or cannot be formed. */
43	    public static String normalizeOrNull(String raw) {
44	        if (raw == null) {
45	            return null;
46	        }
47	        try {
48	            return normalize(raw);
49	        }
50	        catch (InvalidTelephoneException ex) {
51	            return null;
52	        }
53	    }
54	}
