3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Rolls a registration date forward to a business day: a Saturday or Sunday is rolled
8	 * forward to the following Monday; a weekday is returned unchanged. Used for the effective
9	 * registration date (supplied on the request or defaulted to the server date) so that the
10	 * stored {@code registrationDate} — and everything derived from it — always falls on a
11	 * business day.
12	 */
13	public final class BusinessDay {
14	
15	    private BusinessDay() {
16	    }
17	
18	    public static LocalDate roll(LocalDate date) {
19	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
20	            date = date.plusDays(1);
21	        }
22	        return date;
23	    }
24	}
