22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
24	    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
25	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /**
29	     * Fixed city-to-region table used to derive the owner's locality.
30	     */
31	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
32	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    /**
35	     * Derives the owner's locality (region) from the city via the fixed city-to-region
36	     * table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or {@code UNKNOWN} when the city
37	     * is not in the table.
38	     */
39	    default String toLocality(Owner owner) {
40	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
41	    }
42	
43	    /**
44	     * Derives the owner's numeric membership level (1 to 3), computed on creation: start at 1;
45	     * add 1 when an email is present; add 1 when the owner has no namesakes ({@code namesakeCount}
46	     * is 0); capped at 3 (level 4 is reserved for tenure).
47	     */
48	    default Integer toMembershipLevel(Owner owner) {
49	        int level = 1;
50	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
51	        if (hasEmail) {
52	            level++;
53	        }
54	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
55	        if (unique) {
56	            level++;
57	        }
58	        return Math.min(level, 3);
59	    }
60	
61	    /**
62	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
63	     * last two digits of the registration-date year (e.g. {@code SMI-0007-M26}). Returns null
64	     * when either the customer code or registration date is absent (e.g. unmigrated seed data).
65	     */
66	    default String toMembershipNumber(Owner owner) {
67	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
68	            return null;
69	        }
